/**
 * ============================================================================
 * HANDLE ESCALATION - Flowise Tool
 * ============================================================================
 * Self-contained tool with built-in error handling.
 * Calls Node-RED endpoint that handles escalation requests with patient information.
 */

const fetch = require('node-fetch');

// ============================================================================
// 📝 CONFIG - Change these values for your setup
// ============================================================================

const CONFIG = {
    toolName: 'handleEscalation',

    // Node-RED endpoint (handles escalation + API calls)
    // TODO: Update this endpoint URL to match your Node-RED service
    endpoint: 'https://c1-aicoe-nodered-lb.prod.c1conversations.io/FabricWorkflow/api/chord/handleEscalation',
    method: 'POST',

    // Build request body from Flowise parameters
    buildBody: () => {
        try {
            // Helper function to normalize values: replace undefined, null, or empty with "NA"
            const normalizeValue = (value) => {
                // Check for undefined
                if (typeof value === 'undefined') {
                    return 'NA';
                }
                // Check for null (including different null types)
                if (value === null || value === 'null' || value === 'NULL') {
                    return 'NA';
                }
                // Check for empty string or whitespace-only string
                if (typeof value === 'string' && value.trim() === '') {
                    return 'NA';
                }
                // Return the value as-is if it's valid
                return value;
            };

            console.log('[handleEscalation] Building request body...');
            console.log('[handleEscalation] Raw variables:', {
                firstName: typeof $firstName !== 'undefined' ? $firstName : 'UNDEFINED',
                lastName: typeof $lastName !== 'undefined' ? $lastName : 'UNDEFINED',
                DOB: typeof $DOB !== 'undefined' ? $DOB : 'UNDEFINED',
                escalationIntent: typeof $escalationIntent !== 'undefined' ? $escalationIntent : 'UNDEFINED',
                vars: typeof $vars !== 'undefined' ? $vars : 'UNDEFINED'
            });

            // Set default value only if c1mg_uui is null, empty, or unresolved (literal "c1mg_uui" string)
            if (!$vars || !$vars.c1mg_uui || $vars.c1mg_uui === 'c1mg_uui' || (typeof $vars.c1mg_uui === 'string' && $vars.c1mg_uui.trim() === '')) {
                if (!$vars) {
                    $vars = {};
                }
                $vars.c1mg_uui = '767202758-000000000001105456-SR-000-000000000000DAL130-5DEAFCC2|77523|223076809|1767202758-000000000001105456-SR-000-000000000000DAL130-5DEAFCC2|junkVO|fdfee190-1e65-4c40-b512-1bb378dcdcab|FSV';
            }

            // Safely access variables and normalize them (replace undefined/null/empty with "NA")
            const firstName = normalizeValue(typeof $firstName !== 'undefined' ? $firstName : undefined);
            const lastName = normalizeValue(typeof $lastName !== 'undefined' ? $lastName : undefined);
            const DOB = normalizeValue(typeof $DOB !== 'undefined' ? $DOB : undefined);
            const escalationIntent = normalizeValue(typeof $escalationIntent !== 'undefined' ? $escalationIntent : undefined);

            const body = {
                firstName: firstName,
                lastName: lastName,
                DOB: DOB,
                escalationIntent: escalationIntent,
                uui: $vars.c1mg_uui,
                EllyConversationID: $vars.sessionId
                //findnigConvId: $vars.Conversation-ID
            };

            console.log('[handleEscalation] Built body:', JSON.stringify(body, null, 2));
            console.log('[handleEscalation] Normalized values:', {
                firstName: firstName,
                lastName: lastName,
                DOB: DOB,
                escalationIntent: escalationIntent
            });
            return body;
        } catch (error) {
            console.error('[handleEscalation] Error building body:', error.message);
            console.error('[handleEscalation] Error stack:', error.stack);
            throw new Error(`Failed to build request body: ${error.message}`);
        }
    },

    // Basic Authentication - Optional, only used if username and password are provided
    getAuthHeader: () => {
        try {
            const username = "workflowapi";
            const password = "e^@V95&6sAJReTsb5!iq39mIC4HYIV";

            // Only create auth header if both username and password exist
            if (username && password) {
                const credentials = Buffer.from(`${username}:${password}`).toString('base64');
                return `Basic ${credentials}`;
            }
        } catch (e) {
            // Variables not defined in Flowise, skip authentication
            return null;
        }
        return null;
    },

    headers: {},
    timeout: 30000,

    buildSuccessMessage: (result) => {
        // Return the full response from Node-RED
        console.log('[handleEscalation] Full Node-RED response:', JSON.stringify(result));
        return result;
    },

    buildErrorMessage: (error) => ({
        error: 'Failed to handle escalation',
        message: error.message,
        timestamp: new Date().toISOString()
    })
};

// ============================================================================
// 🚀 HTTP REQUEST ENGINE
// ============================================================================

async function executeRequest() {
    console.log(`[${CONFIG.toolName}] ===== EXECUTE REQUEST CALLED =====`);
    console.log(`[${CONFIG.toolName}] Starting execution`);
    console.log(`[${CONFIG.toolName}] Endpoint: ${CONFIG.method} ${CONFIG.endpoint}`);

    // Immediately check if variables are accessible
    try {
        console.log(`[${CONFIG.toolName}] Checking variable accessibility...`);
        const varCheck = {
            firstNameExists: typeof $firstName !== 'undefined',
            lastNameExists: typeof $lastName !== 'undefined',
            DOBExists: typeof $DOB !== 'undefined',
            escalationIntentExists: typeof $escalationIntent !== 'undefined',
            varsExists: typeof $vars !== 'undefined'
        };
        console.log(`[${CONFIG.toolName}] Variable check:`, JSON.stringify(varCheck));
    } catch (varError) {
        console.error(`[${CONFIG.toolName}] ERROR checking variables:`, varError.message);
        throw new Error(`Variable access error: ${varError.message}`);
    }

    try {
        let url = CONFIG.endpoint;
        let body = null;

        if (CONFIG.method.toUpperCase() === 'GET' && CONFIG.buildQueryParams) {
            const queryString = CONFIG.buildQueryParams();
            url = `${CONFIG.endpoint}?${queryString}`;
            console.log(`[${CONFIG.toolName}] Endpoint: ${CONFIG.method} ${url}`);
        } else if (['POST', 'PUT', 'PATCH'].includes(CONFIG.method.toUpperCase())) {
            console.log(`[${CONFIG.toolName}] Calling buildBody...`);
            body = CONFIG.buildBody ? CONFIG.buildBody() : null;
            if (body) {
                console.log(`[${CONFIG.toolName}] Request Body built successfully:`, JSON.stringify(body, null, 2));
            } else {
                console.warn(`[${CONFIG.toolName}] Warning: buildBody returned null or undefined`);
            }
        }

        const headers = {
            'Content-Type': 'application/json',
            ...CONFIG.headers
        };

        // Add Authorization header only if credentials are provided
        const authHeader = CONFIG.getAuthHeader();
        if (authHeader) {
            headers['Authorization'] = authHeader;
        }

        const options = {
            method: CONFIG.method.toUpperCase(),
            headers: headers
        };

        if (body) {
            options.body = JSON.stringify(body);
        }

        // Add timeout if AbortController is available
        let timeoutId;
        if (typeof AbortController !== 'undefined') {
            const controller = new AbortController();
            timeoutId = setTimeout(() => controller.abort(), CONFIG.timeout);
            options.signal = controller.signal;
        }

        console.log(`[${CONFIG.toolName}] Making request to: ${url}`);
        console.log(`[${CONFIG.toolName}] Request options:`, JSON.stringify({
            method: options.method,
            headers: Object.keys(options.headers),
            hasBody: !!options.body,
            bodyLength: options.body ? options.body.length : 0
        }, null, 2));

        const response = await fetch(url, options);

        if (timeoutId) {
            clearTimeout(timeoutId);
        }

        console.log(`[${CONFIG.toolName}] Response Status: ${response.status} ${response.statusText}`);

        let data;
        const contentType = response.headers.get('content-type');
        if (contentType && contentType.includes('application/json')) {
            data = await response.json();
        } else {
            data = await response.text();
        }

        if (!response.ok) {
            console.error(`[${CONFIG.toolName}] HTTP Error ${response.status}:`, data);
            throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }

        // Check if Node-RED returned an error in the payload (even with 200 OK)
        if (data && data.success === false) {
            console.error(`[${CONFIG.toolName}] Node-RED Error:`, data);
            throw new Error(data.error || 'Escalation handling failed');
        }

        console.log(`[${CONFIG.toolName}] Success - Escalation handled`);

        const successResponse = CONFIG.buildSuccessMessage(data);
        return JSON.stringify(successResponse);

    } catch (error) {
        console.error(`[${CONFIG.toolName}] Error:`, error.message);
        console.error(`[${CONFIG.toolName}] Error Type:`, error.name);

        if (error.name === 'AbortError') {
            console.error(`[${CONFIG.toolName}] Request timed out after ${CONFIG.timeout}ms`);
            error.message = `Request timeout after ${CONFIG.timeout}ms`;
        }

        // Build detailed error response
        const errorResponse = CONFIG.buildErrorMessage(error);
        const errorMessage = JSON.stringify(errorResponse, null, 2);

        // THROW the error to make Flowise show RED (with structured message)
        throw new Error(errorMessage);
    }
}

// Execute and return the result (Flowise needs this)
// Add immediate logging to verify function is being called
console.log('[handleEscalation] ===== TOOL SCRIPT LOADED =====');
console.log('[handleEscalation] About to call executeRequest()...');

// Return the promise - Flowise will handle awaiting it
return executeRequest().catch(error => {
    console.error('[handleEscalation] ===== UNHANDLED ERROR IN PROMISE =====');
    console.error('[handleEscalation] Error:', error.message);
    console.error('[handleEscalation] Error type:', error.name);
    console.error('[handleEscalation] Error stack:', error.stack);
    // Re-throw to ensure Flowise sees the error
    throw error;
});
